import logging
import time
import random

class DataProcessor:
    def __init__(self, max_retries=3, retry_delay=5):
        self.max_retries = max_retries
        self.retry_delay = retry_delay
        self.logger = logging.getLogger(__name__)

    def process_data(self, data):
        # Simulate data processing failure
        if random.random() < 0.5:
            raise Exception('Data processing failed')
        return data

    def retry_with_alert(self, data):
        retries = 0
        while retries <= self.max_retries:
            try:
                return self.process_data(data)
            except Exception as e:
                self.logger.error(f'Data processing failed: {e}')
                if retries < self.max_retries:
                    self.logger.info(f'Retrying in {self.retry_delay} seconds...')
                    time.sleep(self.retry_delay)
                retries += 1
        self.logger.error('All retries failed. Sending alert...')
        # Send alert logic here
        return None

data_processor = DataProcessor()
result = data_processor.retry_with_alert('sample_data')
if result is not None:
    print('Data processed successfully')
else:
    print('Data processing failed after retries')
